class Solution {
public:
    int minChanges(vector<int>& nums, int k) {
        int n = nums.size();
        vector<int> diff(k + 2, 0);
        for (int i = 0; i < n / 2; ++i) {
            int a = nums[i];
            int b = nums[n - 1 - i];
            int d = abs(a - b);
            int m = max({a, b, k - a, k - b});
            diff[0] += 1;
            diff[d] -= 1;
            diff[d + 1] += 1;
            diff[m + 1] += 1;
        }
        int curr = 0;
        int min_changes = n;
        for (int x = 0; x <= k; ++x) {
            curr += diff[x];
            if (curr < min_changes) {
                min_changes = curr;
            }
        }
        return min_changes;
    }
};

class Solution {
    public int minChanges(int[] nums, int k) {
        int n = nums.length;
        int[] diff = new int[k + 2];
        for (int i = 0; i < n / 2; ++i) {
            int a = nums[i];
            int b = nums[n - 1 - i];
            int d = Math.abs(a - b);
            int m = Math.max(Math.max(a, b), Math.max(k - a, k - b));
            diff[0] += 1;
            diff[d] -= 1;
            diff[d + 1] += 1;
            diff[m + 1] += 1;
        }
        int curr = 0;
        int minChanges = n;
        for (int x = 0; x <= k; ++x) {
            curr += diff[x];
            if (curr < minChanges) {
                minChanges = curr;
            }
        }
        return minChanges;
    }
}

